# One unique top-level function per file. Auto-generated from top-level function definitions.
from __future__ import annotations
import numpy as np
import pandas as pd
import os
import re


def neutral_losses_from_consensus_spectra(consensus_spectra_files,
                                          mz_col = "median_mz(Da)",
                                          intensity_col = "median_Int",
                                          iqr_mz_ppm_col = "IQR_mz(ppm)",
                                          iqr_mz_da_col = "IQR_mz(Da)",
                                          min_mz_col = "min_mz(Da)",
                                          max_mz_col = "max_mz(Da)",
                                          min_neutral_loss = 18.0,
                                          max_neutral_loss = None,
                                          min_fragment_intensity = 0,
                                          pair_intensity = "min",
                                          neutral_loss_iqr_rule = "max_fragment_iqr"):
    """
    Extract possible neutral losses from consensus MS2 spectra using the same
    table structure generated by fragments_from_consensus_spectra.

    The returned neutral-loss table is compatible with:

        compress_fragment_intervals_by_overlap(all_fragment_mz_table = table,
                                               mz_col = 4,
                                               min_mz_col = 6,
                                               max_mz_col = 7)

    Output columns begin as:

        0 spectrum_id
        1 feature_id
        2 source_file
        3 fragment_id
        4 mz_col
        5 iqr_mz_ppm_col
        6 min_mz_col
        7 max_mz_col

    For neutral losses, fragment_id is the neutral-loss row id within the
    consensus spectrum.

    neutral_loss_iqr_rule:
        "max_fragment_iqr" -> neutral-loss IQR is max(low fragment IQR,
                              high fragment IQR)
        "quadrature"       -> neutral-loss IQR is sqrt(low_iqr^2 + high_iqr^2)
    """

    if pair_intensity not in ["min",
                              "geometric_mean",
                              "mean",
                              "product",
                              "binary"]:
        raise ValueError("Unknown pair_intensity: " + str(pair_intensity))

    if neutral_loss_iqr_rule not in ["max_fragment_iqr",
                                     "quadrature"]:
        raise ValueError("neutral_loss_iqr_rule must be 'max_fragment_iqr' or 'quadrature'.")

    neutral_loss_tables = []
    feature_id_map_rows = []

    for spectrum_id, consensus_spectra_file in enumerate(consensus_spectra_files):

        consensus_spectra_df = pd.read_csv(consensus_spectra_file,
                                           index_col = 0)

        if mz_col not in consensus_spectra_df.columns:
            raise ValueError("Missing mz_col in "
                             + str(consensus_spectra_file)
                             + ": "
                             + str(mz_col))

        if intensity_col not in consensus_spectra_df.columns:
            raise ValueError("Missing intensity_col in "
                             + str(consensus_spectra_file)
                             + ": "
                             + str(intensity_col))

        source_file = os.path.basename(consensus_spectra_file)

        feature_id_search = re.search(r"Consensus_ms2-spectra_(\d+)",
                                      source_file)

        if feature_id_search is None:
            feature_id = spectrum_id

        else:
            feature_id = int(feature_id_search.group(1))

        feature_id_map_rows.append({"spectrum_id": int(spectrum_id),
                                    "feature_id": int(feature_id),
                                    "source_file": source_file})

        fragment_mz = pd.to_numeric(consensus_spectra_df[mz_col],
                                    errors = "coerce").to_numpy(dtype = float)

        fragment_intensity = pd.to_numeric(consensus_spectra_df[intensity_col],
                                           errors = "coerce").to_numpy(dtype = float)

        fragment_ids = np.arange(len(consensus_spectra_df),
                                 dtype = int)

        if iqr_mz_da_col in consensus_spectra_df.columns:

            fragment_iqr_da = pd.to_numeric(consensus_spectra_df[iqr_mz_da_col],
                                            errors = "coerce").to_numpy(dtype = float)

        elif iqr_mz_ppm_col in consensus_spectra_df.columns:

            fragment_iqr_ppm = pd.to_numeric(consensus_spectra_df[iqr_mz_ppm_col],
                                             errors = "coerce").to_numpy(dtype = float)

            fragment_iqr_da = fragment_iqr_ppm / 1e6 * fragment_mz

        elif min_mz_col in consensus_spectra_df.columns and max_mz_col in consensus_spectra_df.columns:

            fragment_min_mz = pd.to_numeric(consensus_spectra_df[min_mz_col],
                                            errors = "coerce").to_numpy(dtype = float)

            fragment_max_mz = pd.to_numeric(consensus_spectra_df[max_mz_col],
                                            errors = "coerce").to_numpy(dtype = float)

            fragment_iqr_da = np.abs(fragment_max_mz - fragment_min_mz)

        else:

            fragment_iqr_da = np.zeros(len(consensus_spectra_df),
                                       dtype = float)

        fragment_iqr_da = np.where(np.isfinite(fragment_iqr_da) & (fragment_iqr_da >= 0),
                                   fragment_iqr_da,
                                   0.0)

        fragments_loc = (np.isfinite(fragment_mz) &
                         np.isfinite(fragment_intensity) &
                         (fragment_intensity > min_fragment_intensity))

        if np.sum(fragments_loc) < 2:
            continue

        fragment_mz = fragment_mz[fragments_loc]
        fragment_intensity = fragment_intensity[fragments_loc]
        fragment_iqr_da = fragment_iqr_da[fragments_loc]
        fragment_ids = fragment_ids[fragments_loc]

        order = np.argsort(fragment_mz)

        fragment_mz = fragment_mz[order]
        fragment_intensity = fragment_intensity[order]
        fragment_iqr_da = fragment_iqr_da[order]
        fragment_ids = fragment_ids[order]

        n_fragments = len(fragment_mz)

        neutral_loss_rows = []
        neutral_loss_id = 0

        for low_id in range(n_fragments - 1):

            start_id = np.searchsorted(fragment_mz,
                                       fragment_mz[low_id] + min_neutral_loss,
                                       side = "left")

            if max_neutral_loss is None:
                stop_id = n_fragments

            else:
                stop_id = np.searchsorted(fragment_mz,
                                          fragment_mz[low_id] + max_neutral_loss,
                                          side = "right")

            if start_id >= stop_id:
                continue

            high_ids = np.arange(start_id,
                                 stop_id,
                                 dtype = int)

            neutral_loss_mz = fragment_mz[high_ids] - fragment_mz[low_id]

            low_intensity = np.repeat(fragment_intensity[low_id],
                                      len(high_ids))

            high_intensity = fragment_intensity[high_ids]

            if pair_intensity == "min":

                neutral_loss_intensity = np.minimum(low_intensity,
                                                    high_intensity)

            elif pair_intensity == "geometric_mean":

                neutral_loss_intensity = np.sqrt(low_intensity *
                                                 high_intensity)

            elif pair_intensity == "mean":

                neutral_loss_intensity = 0.5 * (low_intensity +
                                                high_intensity)

            elif pair_intensity == "product":

                neutral_loss_intensity = low_intensity * high_intensity

            elif pair_intensity == "binary":

                neutral_loss_intensity = np.ones(len(high_ids),
                                                 dtype = float)

            low_iqr_da = np.repeat(fragment_iqr_da[low_id],
                                   len(high_ids))

            high_iqr_da = fragment_iqr_da[high_ids]

            if neutral_loss_iqr_rule == "max_fragment_iqr":

                neutral_loss_iqr_da = np.maximum(low_iqr_da,
                                                 high_iqr_da)

            elif neutral_loss_iqr_rule == "quadrature":

                neutral_loss_iqr_da = np.sqrt(low_iqr_da ** 2 +
                                              high_iqr_da ** 2)

            neutral_loss_min_mz = neutral_loss_mz - 0.5 * neutral_loss_iqr_da
            neutral_loss_max_mz = neutral_loss_mz + 0.5 * neutral_loss_iqr_da

            neutral_loss_iqr_ppm = np.where(neutral_loss_mz != 0,
                                            neutral_loss_iqr_da / neutral_loss_mz * 1e6,
                                            np.nan)

            current_n_losses = len(high_ids)

            current_loss_df = pd.DataFrame({
                "spectrum_id": np.repeat(int(spectrum_id),
                                         current_n_losses),
                "feature_id": np.repeat(int(feature_id),
                                        current_n_losses),
                "source_file": np.repeat(source_file,
                                         current_n_losses),
                "fragment_id": np.arange(neutral_loss_id,
                                         neutral_loss_id + current_n_losses,
                                         dtype = int),

                mz_col: neutral_loss_mz,
                iqr_mz_ppm_col: neutral_loss_iqr_ppm,
                min_mz_col: neutral_loss_min_mz,
                max_mz_col: neutral_loss_max_mz,

                intensity_col: neutral_loss_intensity,

                "fragment_mz": neutral_loss_mz,
                "fragment_intensity": neutral_loss_intensity,

                "neutral_loss_mz": neutral_loss_mz,
                "neutral_loss_intensity": neutral_loss_intensity,
                "neutral_loss_iqr_da": neutral_loss_iqr_da,
                "neutral_loss_iqr_ppm": neutral_loss_iqr_ppm,
                "neutral_loss_min_mz": neutral_loss_min_mz,
                "neutral_loss_max_mz": neutral_loss_max_mz,

                "fragment_low_id": np.repeat(fragment_ids[low_id],
                                             current_n_losses),
                "fragment_high_id": fragment_ids[high_ids],
                "fragment_low_mz": np.repeat(fragment_mz[low_id],
                                             current_n_losses),
                "fragment_high_mz": fragment_mz[high_ids],
                "fragment_low_intensity": low_intensity,
                "fragment_high_intensity": high_intensity,
                "fragment_low_iqr_da": low_iqr_da,
                "fragment_high_iqr_da": high_iqr_da
            })

            neutral_loss_rows.append(current_loss_df)

            neutral_loss_id += current_n_losses

        if len(neutral_loss_rows) > 0:

            neutral_losses_current_spectrum_df = pd.concat(neutral_loss_rows,
                                                           ignore_index = True)

            neutral_losses_current_spectrum_df = neutral_losses_current_spectrum_df.sort_values(mz_col)

            neutral_loss_tables.append(neutral_losses_current_spectrum_df)

    feature_id_map_df = pd.DataFrame(feature_id_map_rows)

    if len(neutral_loss_tables) == 0:

        neutral_losses_df = pd.DataFrame()

    else:

        neutral_losses_df = pd.concat(neutral_loss_tables,
                                      ignore_index = True)

    return {"neutral_losses_df": neutral_losses_df,
            "fragments_df": neutral_losses_df,
            "feature_id_map_df": feature_id_map_df}
